import{_ as r,C as s,c as n,o as i,a3 as a,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Tags","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/configuration/tags.md","filePath":"master/sales/crm/configuration/tags.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/configuration/tags.md"};function d(g,e,c,h,u,m){const t=s("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=a('<h1 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h1><p>Tags are short coloured labels that you stick on leads and opportunities. You use them to group deals by topic, such as product line or kind of service, and to find them again with a filter.</p><blockquote><p><strong>In simple words:</strong> A tag is a coloured sticker you put on a deal.</p></blockquote><p>Open <code>CRM → Configuration → Pipeline → Tags</code>.</p><h2 id="the-tag-list" tabindex="-1">The tag list <a class="header-anchor" href="#the-tag-list" aria-label="Permalink to &quot;The tag list&quot;">​</a></h2>',5)),o(t,{src:"/images1/crm/tags-list.png",alt:"Tags list with Consulting, Product, Services, Software, Training and Upsell, each with a colour swatch"}),e[1]||(e[1]=a('<p>The default tags are <strong>Consulting</strong>, <strong>Product</strong>, <strong>Services</strong>, <strong>Software</strong>, <strong>Training</strong> and <strong>Upsell</strong>.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Tag Name:</em></strong> The name of the tag. You can sort by it.</li><li><strong><em>Color:</em></strong> A swatch of the tag colour.</li><li><strong><em>Created By:</em></strong> The user who made the tag.</li><li><strong><em>Created At:</em></strong> Hidden at first. Show it with the column toggle.</li></ul><h3 id="search-sort-and-export" tabindex="-1">Search, sort and export <a class="header-anchor" href="#search-sort-and-export" aria-label="Permalink to &quot;Search, sort and export&quot;">​</a></h3><ul><li>Type in the search box to find a tag.</li><li>Click a column heading to sort. The list starts sorted by name.</li><li>Select rows and use the bulk action to export them.</li></ul><h3 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h3><ul><li><strong>View:</strong> Opens a small card with the <strong>Tag Name</strong> and <strong>Color</strong>.</li><li><strong>Edit:</strong> Changes the tag.</li><li><strong>Delete:</strong> Removes the tag.</li></ul><h2 id="create-a-tag" tabindex="-1">Create a tag <a class="header-anchor" href="#create-a-tag" aria-label="Permalink to &quot;Create a tag&quot;">​</a></h2><ol><li>Go to <code>CRM → Configuration → Pipeline → Tags</code>.</li><li>Click <strong>New Tag</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',9)),o(t,{src:"/images1/crm/tags-form.png",alt:"Create Tag dialog filled with the name Hardware and a purple colour picked"}),e[2]||(e[2]=a('<ul><li><strong><em>Tag Name:</em></strong> The label text. Required. Up to 255 characters. Two tags cannot have the same name.</li><li><strong><em>Color:</em></strong> The colour of the tag. Pick it from the colour picker or type a hex code such as <code>#3b82f6</code>. Optional.</li></ul><p><strong>Example:</strong> Name <code>Hardware</code> and pick a blue colour. A notice says the tag was created.</p><h2 id="use-a-tag" tabindex="-1">Use a tag <a class="header-anchor" href="#use-a-tag" aria-label="Permalink to &quot;Use a tag&quot;">​</a></h2><p>Add tags in the <strong>Tags</strong> field of a lead or an opportunity. You can pick more than one. Tags show on pipeline cards and on forecast cards in their colour. See <a href="./../acquire-leads/create-lead.html">Create a lead</a>.</p><h2 id="edit-and-delete" tabindex="-1">Edit and delete <a class="header-anchor" href="#edit-and-delete" aria-label="Permalink to &quot;Edit and delete&quot;">​</a></h2><ol><li>Click <strong>Edit</strong>, change the name or colour, then click <strong>Save</strong>. A notice says <strong>Tag updated</strong>.</li><li>Click <strong>Delete</strong> and confirm to remove a tag. A notice says <strong>Tag deleted</strong>.</li></ol><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>A tag is shared. Every lead and opportunity can use the same tag.</li><li>Editing a tag changes it everywhere it is used.</li><li>Lead generation rules can also add tags to the leads they create. See <a href="./../acquire-leads/lead-generation.html">Lead generation</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../acquire-leads/create-lead.html">Create a lead</a></li><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./">CRM configuration</a></li></ul>',10))])}const T=r(l,[["render",d]]);export{f as __pageData,T as default};
